const gridSize = 200;
const rate = 0.8;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);
	noFill();
	frameRate(5);
}

function draw() {
	let col1 = 0;
	let col2 = 255;
	/*
	if(random()<0.5){
		col1 = 255;
		col2 = 0;
	}
	*/
	push();
	translate(round((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/gridSize)*gridSize, round((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/gridSize)*gridSize);

	fill(0);
	rect(-gridSize/2, -gridSize/2, gridSize, gridSize);
	noFill();

	let size = random(gridSize/8, gridSize/2);
	for(let j = 0 ; j < 4; j++){
		if(random()<rate) continue;
		stroke(col1);
		strokeWeight(12);
		circle(0, 0, j/4*size*2);
		stroke(col2);
		strokeWeight(4);
		circle(0, 0, j/4*size*2);
	}
	for(let j = 0; j < 10; j++){
		if(random()<rate) continue;
		push();
		rotate(j/10*PI);
		if(random()<rate) {
			stroke(col1);
			strokeWeight(8);
			line(-size, 0, size, 0);
			stroke(col2);
			strokeWeight(2);
			line(-size, 0, size, 0);
		}
		for(let i = 0; i < 10; i++){
			if(random()<rate) continue;
			let x = ((i / 10) - 0.5) * size * 2;
			push();
				translate(x, 0);
				rotate(PI/4);

				stroke(col1);
				strokeWeight(8);
				line(0, 10, 0, -10);
				stroke(col2);
				strokeWeight(2);
				line(0, 10, 0, -10);
			pop();
		}
		for(let i = 0; i < 10; i++){
			if(random()<rate) continue;
			var x = ((i / 10) - 0.5) * size * 2;
			push();
				translate(x, 0);
				rotate(-PI/4);

				stroke(col1);
				strokeWeight(8);
				line(0, 10, 0, -10);
				stroke(col2);
				strokeWeight(2);
				line(0, 10, 0, -10);
			pop();
		}
		for(let i = 0; i < 10; i++){
			if(random()<rate) continue;
			var x = ((i / 10) - 0.5) * size * 2;
			stroke(0);
			strokeWeight(8);
			circle(x, 0, 10);
			stroke(255);
			strokeWeight(2);
			circle(x, 0, 10);
		}
		for(let i = 0; i < 10; i++){
			if(random()<rate) continue;
			var x = ((i / 10) - 0.5) * size * 2;
			stroke(col1);
			strokeWeight(8);
			circle(x, 0, 30);
			stroke(col2);
			strokeWeight(2);
			circle(x, 0, 30);
		}
		pop();
	}
	pop();
}

function mousePressed(){
	background(0);
}
